 function setWrapFromCloud(img,name,wrap={}){coverSource=img;wrapName=name||'';wrapActive=true;const values={wrapOrder:wrap.order,wrapFit:wrap.fit,wrapScale:wrap.scale,wrapX:wrap.x,wrapY:wrap.y,wrapAngle:wrap.angle,wrapBleed:wrap.bleed,wrapSpine:wrap.spine,wrapBackground:wrap.background};for(const [id,value] of Object.entries(values))if(value!==undefined&&value!==null&&$(id))$(id).value=value;$('wrapFileName').textContent=wrapName||'כריכה';$('wrapStatus').textContent='כריכה רציפה · '+(wrapName||'');rebuildCovers()}
 function getState(){return {scenes:scenes.map(s=>({...s})),movieAspect:$('movieAspect').value,movieQuality:$('movieQuality').value,movieFormat:$('movieFormat').value,movieTextColor:$('movieTextColor').value,wrap:{active:wrapActive,name:wrapName,order:$('wrapOrder').value,fit:$('wrapFit').value,scale:number('wrapScale'),x:number('wrapX'),y:number('wrapY'),angle:number('wrapAngle'),bleed:number('wrapBleed'),spine:number('wrapSpine'),background:$('wrapBackground').value},orbit:{rotation:number('rotation'),tilt:number('tilt'),zoom:orbitZoom}}}
 function restoreState(state={}){if(Array.isArray(state.scenes)&&state.scenes.length){scenes.splice(0,scenes.length,...state.scenes.map(s=>({...s})));uid=Math.max(uid,...scenes.map(s=>Number(s.id)||0))}if(state.movieAspect)$('movieAspect').value=state.movieAspect;if(state.movieQuality)$('movieQuality').value=String(state.movieQuality);if(state.movieTextColor)$('movieTextColor').value=state.movieTextColor;if(state.movieFormat&&[...$('movieFormat').options].some(o=>o.value===state.movieFormat))$('movieFormat').value=state.movieFormat;if(state.wrap){const values={wrapOrder:state.wrap.order,wrapFit:state.wrap.fit,wrapScale:state.wrap.scale,wrapX:state.wrap.x,wrapY:state.wrap.y,wrapAngle:state.wrap.angle,wrapBleed:state.wrap.bleed,wrapSpine:state.wrap.spine,wrapBackground:state.wrap.background};for(const [id,value] of Object.entries(values))if(value!==undefined&&value!==null&&$(id))$(id).value=value;wrapName=state.wrap.name||wrapName}if(state.orbit){if(state.orbit.rotation!=null)$('rotation').value=state.orbit.rotation;if(state.orbit.tilt!=null)$('tilt').value=state.orbit.tilt;if(state.orbit.zoom!=null)orbitZoom=state.orbit.zoom}invalidate();renderScenes();configureSize()}
 async function serverRender(config={}){if(config.scenes?.length){scenes.splice(0,scenes.length,...config.scenes.map(s=>({...s})));uid=Math.max(uid,...scenes.map(s=>Number(s.id)||0))}if(config.aspect)$('movieAspect').value=config.aspect;if(config.quality)$('movieQuality').value=String(config.quality);if(config.textColor)$('movieTextColor').value=config.textColor;if(config.format&&[...$('movieFormat').options].some(o=>o.value===config.format))$('movieFormat').value=config.format;renderScenes();configureSize();$('movieEmpty').hidden=true;await start(true)}
